// 加载 @sentry/nextjs。Node 包解析到它的 server 入口，这里的 init 是 Node SDK 的 init。
// 这行在求值时就会执行。DSN 为空也会把 SDK 载入内存，只是下面不会调用 init。
import * as Sentry from "@sentry/nextjs";

// 服务端 DSN 优先。未设置或空字符串时，改用浏览器那份公开 DSN。两份都空则得到空字符串。
const dsn = process.env.SENTRY_DSN || process.env.NEXT_PUBLIC_SENTRY_DSN;

// 空字符串在 JS 里是 falsy。没有 DSN 就跳过整个 init，进程里不创建 Sentry 客户端。
if (dsn) {
  // 同步初始化。返回的客户端没有接住；SDK 会把它放到当前 scope 上，供后续 capture 使用。
  Sentry.init({
    // 事件要送到的项目地址。上面算出的非空字符串原样传入。
    dsn,

    // 性能追踪的抽样率。生产环境每条 trace 约 10% 会发送，其他 NODE_ENV 为 100%。
    // 这项只决定追踪。错误事件另有默认 sampleRate 1，不按这个 0.1 抽样。
    tracesSampleRate: process.env.NODE_ENV === "production" ? 0.1 : 1.0,

    // 开发环境打开 SDK 自己的调试日志。生产环境和 test 关闭。
    debug: process.env.NODE_ENV === "development",
    // 写进每条事件的 environment。Next 会把 NODE_ENV 设成 development、production 或 test。
    // 这里显式传入后，SDK 不再用 SENTRY_ENVIRONMENT 填这项。
    environment: process.env.NODE_ENV,

    // 开发环境为 true 时，SDK 加上 Spotlight 集成，把即将发送的信封再 POST 一份到本机 8969。
    // sidecar 没启动时，失败只记调试警告；连续失败超过 3 次后，这个进程不再转发。
    spotlight: process.env.NODE_ENV === "development",

    // 错误事件和消息事件发送前的最后一道过滤。init 时只登记，此时不调用。
    beforeSend(event, hint) {
      // 开发环境先打印再丢弃。异常正文常常在 event.exception 里，这里的 event.message 可能是 undefined。
      if (process.env.NODE_ENV === "development") {
        // 只进本机终端，方便看到“捕获发生过”。返回 null 之前事件还没离开进程。
        console.log(
          // 固定前缀，和 Edge、浏览器那两份配置的日志区分开。
          "[Sentry Server] Event captured (dev mode):",
          // 事件上的 message 字段。captureException 的场景里经常没有这个字段。
          event.message
        );
        // null 让 SDK 丢掉事件，不生成信封。开发环境因此也不会转到 Spotlight。
        return null;
      }

      // 生产环境才走到这里。hint.originalException 是 captureException 收到的原始抛出值。
      const error = hint.originalException;
      // 只有 Error 实例才看 message。字符串、普通对象或其他抛出值继续往下，最终放行。
      if (error instanceof Error) {
        // message 里出现这串子串就丢弃。常见于对端关掉连接。看的是 message，不看 error.code。
        if (error.message.includes("ECONNRESET")) {
          // 丢弃这条连接重置，不上报。
          return null;
        }
        // 两个子串都区分大小写。消息里带 Unauthorized 或 Not Found 就视为预期失败，不上报。
        if (
          // 文本里包含 Unauthorized。
          error.message.includes("Unauthorized") ||
          // 文本里包含 Not Found。
          error.message.includes("Not Found")
        ) {
          // 丢弃这条预期失败。
          return null;
        }
      }

      // 原样放行。SDK 接着按 DSN 发送；开发环境的 Spotlight 只复制这种已经放行的信封。
      return event;
