/*
 * prisma/schema.prisma — 数据库形状的声明，不是业务数据，也不是可执行脚本。
 *
 * 在项目里做什么：
 * 项目是 Fracture Recovery Companion（骨折康复陪伴）。用户、登录会话、
 * 康复档案、开通记录、14 天计划和聚合统计都存在 PostgreSQL 里。这个文件
 * 只写下那些表有哪些字段和关系。dev 和 prod 各有一套库，两边可以共用这一份
 * 声明，但库里的行不会写进这个文件，这个文件里也没有任何一行用户数据。
 *
 * 用途：
 * 给 Prisma 一份完整的模型图。`prisma generate` 用它生成 TypeScript 客户端，
 * `prisma db push` 用它把目标库的表结构改成和声明一致。页面和 API 不 import
 * 这个文件；它们 import `@/lib/prisma` 里已经生成好的客户端。
 *
 * 实际承担的职责：
 * - 声明枚举、表、字段、默认值、唯一约束、索引，以及 SQL 里的真实表名。
 * - 把 NextAuth 需要的 `User`、`Account`、`Session`、`VerificationToken` 固定下来。
 * - 把当前主路径用到的 `RecoveryProfile`、`Purchase`、`Program`、`ProgramDay`
 *   和只存合计数字的 `MarketingMetricAggregate` 固定下来。
 * - 保留当前 release 暂停的 AI chat 和知识库表，以及 Creem / Stripe 仍会写入的
 *   购买和 webhook 表。购买表的字段名还带着 stripe，免费开通写入的识别码是
 *   `free_access:<userId>`。
 * - `KnowledgeChunk.embedding` 声明为 Postgres pgvector，Prisma 客户端不能把它
 *   当成普通字段读写。
 * 查询、开通计划和完成当天都写在 `src/lib`，不写在这里。
 *
 * 加载顺序和执行顺序：
 *
 * 1. 这个文件没有运行顺序。Prisma CLI 默认读取项目根下的 `prisma/schema.prisma`，
 *    把整份文件解析成一张模型图。`generator` 和 `datasource` 是配置，enum 和
 *    model 是这张图里的类型。模型谁写在前面，不影响建表顺序，也不影响插入顺序。
 * 2. `pnpm install` 的 `postinstall`，以及 `pnpm db:generate`，执行
 *    `prisma generate`。这一步只读本文件，把客户端生成到
 *    `node_modules/.prisma/client`。它不改数据库，也不把库里的行抄回来。
 * 3. `pnpm exec prisma db push` 再读整份文件。CLI 用 `directUrl`，也就是
 *    `DIRECT_URL`，直连 Postgres，把表、枚举和索引调整到和声明一致。
 *    运行时查询用的是 `url`，也就是 `DATABASE_URL`，通常指向连接池。
 *    仓库没有 migrations 目录，结构同步走 `db push`。
 * 4. `pnpm dev`、`pnpm run prod:dev` 和 `next start` 都不会加载本文件。
 *    请求进来后，第一次 import `@/lib/prisma` 时才创建已经生成好的
 *    `PrismaClient`。`APP_ENV=prod` 时，那个客户端改用校验过的 prod
 *    `DATABASE_URL`。第一次查询才真正连库。
 * 5. 改完本文件后，要重新 `pnpm db:generate`，TypeScript 才认识新字段。
 *    要让某一套库的表跟着变，还要对那一套库执行 `prisma db push`。
 *    只改这个文件，正在跑的网站仍使用旧客户端和旧表。
 */

// 生成器配置。下面指定要生成哪一种客户端。
generator client {
  // 生成 Prisma 的 JavaScript / TypeScript 客户端，包名是 @prisma/client。
  provider = "prisma-client-js"
}

// 数据源配置。它只说明连哪一种数据库，不保存连接串本身。
datasource db {
  // 数据库种类是 PostgreSQL。dev 和 prod 都用 Supabase Postgres。
  provider = "postgresql"
  // 运行时查询用的地址，从环境变量 DATABASE_URL 读取。通常是连接池地址。
  url      = env("DATABASE_URL")
  // CLI 同步表结构用的直连地址，从 DIRECT_URL 读取。db push 走这一条，不走上面的连接池。
  directUrl = env("DIRECT_URL")
}

// 购买记录的状态。当前免费开通会写成 PAID。
enum PurchaseStatus {
  // 已创建，付款或开通还没完成。
  PENDING
  // 已付款，或当前 release 的免费开通已经确认。
  PAID
  // 付款失败。
  FAILED
  // 已退款。
  REFUNDED
}

// 一份 14 天计划的状态。
enum ProgramStatus {
  // 计划正在进行。
  ACTIVE
  // 计划已经完成。
  COMPLETED
  // 计划已过期。
  EXPIRED
}

// 一次 AI 对话的状态。当前 release 的 AI chat 是暂停的，表仍保留。
enum ChatConversationStatus {
  // 对话还开着。
  ACTIVE
  // 对话已归档。
  ARCHIVED
}

// 一条聊天消息的角色。
enum ChatMessageRole {
  // 用户发出的消息。
  USER
  // 模型回复的消息。
  ASSISTANT
  // 系统提示或安全规则消息。
  SYSTEM
}

// 知识库文档的来源类别。
enum KnowledgeSourceType {
  // 美国骨科医师学会一类来源。
  AAOS
  // 英国国民保健署一类来源。
  NHS
  // 项目内既有康复资料。
  GUZHE
  // 常见问题。
  FAQ
  // 博客文章。
  BLOG
}

// 登录用户。NextAuth 和后面的业务表都从这里连出去。
model User {
  // 主键。cuid() 在插入时生成一条不透明的字符串 id。
  id            String    @id @default(cuid())
  // 显示名。魔法链接登录可以没有名字，所以可空。
  name          String?
  // 邮箱。有值时必须唯一；未填写时允许为空。
  email         String?   @unique
  // 邮箱完成验证的时间。还没验证时为空。
  emailVerified DateTime?
  // 头像地址。没有头像时为空。
  image         String?
  // 插入这一行时写入当前时间。
  createdAt     DateTime  @default(now())
  // Prisma 在更新这一行时自动改成当前时间。
  updatedAt     DateTime  @updatedAt

  // 这个用户在各登录提供方下的账号。一个用户可以有多条。
  accounts Account[]
  // 这个用户的登录会话。一个用户可以有多条。
  sessions Session[]
  // 康复档案。问号表示最多一条，和 RecoveryProfile.userId 的唯一约束配成一对一。
  recoveryProfile RecoveryProfile?
  // 这个用户的购买或免费开通记录。
  purchases Purchase[]
  // 这个用户的 14 天计划。
  programs Program[]
  // 这个用户的 AI 对话。当前 release 不开启新对话，旧结构仍留着。
  chatConversations ChatConversation[]

  // Postgres 里的真实表名是 users。
  @@map("users")
}

// 用户填写的康复档案。一个用户最多一份。
model RecoveryProfile {
  // 这份档案自己的主键。
  id                   String   @id @default(cuid())
  // 档案属于哪个用户。唯一，所以一个用户不能有第二份档案。
  userId               String   @unique
  // 受伤部位。应用层只接受 finger 或 metacarpal，数据库这里仍是字符串。
  bodyPart             String
  // 部位下面的具体描述，由 onboarding 表单校验长度。
  subType              String
  // 石膏或固定拆除的日期时间。
  castRemovedAt        DateTime
  // 是否有内固定。应用层使用 yes、no、not_sure。
  hasHardware          String
  // 是否已被建议去做物理治疗。应用层使用 yes、no、not_sure。
  referredToPt         String
  // 用户填写的疼痛等级，整数。
  painLevel            Int
  // 受影响的是不是惯用手。
  dominantHandAffected Boolean
  // 日常主要活动类型，例如 desk、manual。合法值由应用层校验。
  jobType              String
  // 用户补充说明。可以不填。
  notes                String?
  // 资格判断产生的风险标记。没有标记时为空。
  riskFlagsJson        Json?
  // 用户确认过的隐私说明版本。还没确认时为空。
  privacyNoticeVersion String?
  // 用户确认隐私说明的时间。还没确认时为空。
  privacyAcknowledgedAt DateTime?
  // 档案创建时间。
  createdAt            DateTime @default(now())
  // 档案每次更新时自动刷新。
  updatedAt            DateTime @updatedAt

  // 连回 User。用户被删时，这份档案一起删。
  user User @relation(fields: [userId], references: [id], onDelete: Cascade)
  // 依据这份档案生成的计划。
  programs Program[]

  // 让 (id, userId) 可以当组合外键的目标，计划必须同时对上档案和同一个用户。
  @@unique([id, userId])
  // 按受伤部位查询时使用。
  @@index([bodyPart])
  // 按拆除固定的日期查询时使用。
  @@index([castRemovedAt])
  // Postgres 里的真实表名是 recovery_profiles。
  @@map("recovery_profiles")
}

// 一次开通或购买。当前免费开通也写在这张表里，金额为 0，状态为 PAID。
model Purchase {
  // 这条开通记录自己的主键。
  id                      String         @id @default(cuid())
  // 开通属于哪个用户。
  userId                  String
  // 开通识别码，全表唯一。免费开通是 free_access:<userId>，本地模拟是 dev_mock:<userId>。
  // Creem 也会把自己的 checkout 引用写进这个仍叫 stripe 的字段。
  stripeCheckoutSessionId String         @unique
  // Stripe PaymentIntent。免费开通和部分兼容路径不写它。
  stripePaymentIntentId   String?        @unique
  // Stripe Customer。没有 Stripe 客户时为空。
  stripeCustomerId        String?
  // 金额的最小货币单位。免费开通写 0。
  amount                  Int
  // 货币代码。免费开通写 usd。
  currency                String
  // 开通状态，缺省是 PENDING。免费开通写入时直接用 PAID。
  status                  PurchaseStatus @default(PENDING)
  // 变成已支付或已开通的时间。还没完成时为空。
  paidAt                  DateTime?
  // 退款时间。没有退款时为空。
  refundedAt              DateTime?
  // 记录创建时间。
  createdAt               DateTime       @default(now())
  // 记录更新时自动刷新。
  updatedAt               DateTime       @updatedAt

  // 连回用户。用户被删时，开通记录一起删。
  user User @relation(fields: [userId], references: [id], onDelete: Cascade)
  // 由这条开通生成的计划。问号表示可以还没有计划。
  program Program?

  // 让 (id, userId) 成为计划表组合外键的目标。
  @@unique([id, userId])
  // 按用户查找他的开通记录。
  @@index([userId])
  // 按状态查找，例如统计已开通。
  @@index([status])
  // Postgres 里的真实表名是 purchases。
  @@map("purchases")
}

// Stripe webhook 的处理记录，用来识别已经处理过的事件。它不连到 User。
model StripeWebhookEvent {
  // 这条处理记录自己的主键。
  id            String   @id @default(cuid())
  // Stripe 事件 id。重复投递时靠这个唯一值认出来。
  stripeEventId String   @unique
  // Stripe 事件类型，例如 checkout.session.completed。
  type          String
  // 本系统处理完的时间。还没处理完时为空。
  processedAt   DateTime?
  // 保留下来的事件正文。可以不存。
  payloadJson   Json?
  // 第一次见到这个事件的时间。
  createdAt     DateTime @default(now())

  // 按事件类型查找。
  @@index([type])
  // Postgres 里的真实表名是 stripe_webhook_events。
  @@map("stripe_webhook_events")
}

// 一份 14 天计划。它必须同时属于一个用户、一份康复档案和一条开通记录。
model Program {
  // 计划主键。
  id                   String        @id @default(cuid())
  // 计划属于哪个用户。
  userId               String
  // 生成计划时使用的康复档案。
  recoveryProfileId    String
  // 对应的开通记录。一条开通记录最多生成一份计划。
  purchaseId           String        @unique
  // 使用的内容模板版本，例如 finger-v1。
  templateVersion      String
  // 计划开始日期。服务层会把时间规整到当天 0 点。
  startDate            DateTime
  // 计划结束日期。开始日加上 13 天，覆盖 14 天。
  endDate              DateTime
  // 用户当前进行到第几天，从 1 开始。
  currentDay           Int           @default(1)
  // 计划状态，新建时是 ACTIVE。
  status               ProgramStatus @default(ACTIVE)
  // 开通时生成的摘要。没有摘要时为空。
  generatedSummaryJson Json?
  // 计划创建时间。
  createdAt            DateTime      @default(now())
  // 计划更新时自动刷新。
  updatedAt            DateTime      @updatedAt

  // 连回用户。用户被删时，计划一起删。
  user User @relation(fields: [userId], references: [id], onDelete: Cascade)
  // 同时对上档案 id 和同一个 userId，避免计划接到另一个用户的档案。
  recoveryProfile RecoveryProfile @relation(fields: [recoveryProfileId, userId], references: [id, userId], onDelete: Cascade)
  // 同时对上开通记录 id 和同一个 userId。
  purchase Purchase @relation(fields: [purchaseId, userId], references: [id, userId], onDelete: Cascade)
  // 这 14 天各自的内容。
  days ProgramDay[]
  // 围绕这份计划产生的 AI 对话。
  chatConversations ChatConversation[]

  // 让 (id, userId) 可以当对话表组合外键的目标。
  @@unique([id, userId])
  // 同一条开通记录和同一个用户只能对应一份计划。
  @@unique([purchaseId, userId])
  // 按用户查找计划。
  @@index([userId])
  // 按计划状态查找。
  @@index([status])
  // 按当前进行到的天数查找。
  @@index([currentDay])
  // Postgres 里的真实表名是 programs。
  @@map("programs")
}

// 计划中的某一天。内容来自 content/ 里的模板，完成进度写在这一行。
model ProgramDay {
  // 这一天自己的主键。
  id                     String    @id @default(cuid())
  // 属于哪一份计划。
  programId              String
  // 第几天，取值 1 到 14。同一份计划里这个数字不能重复。
  dayIndex               Int
  // 这一天所属阶段，例如 early_mobility。
  stage                  String
  // 这一天要展示的标题、动作和安全提醒，整块存成 JSON。
  contentJson            Json
  // 预计用时，单位是分钟。
  estimatedMinutes       Int
  // 用户已经勾选的练习 slug。Postgres 里是字符串数组，缺省为空数组。
  completedExerciseSlugs String[]  @default([])
  // 这一天被判定完成的时间。还没完成时为空。
  completedAt            DateTime?
  // 完成百分比，新建时是 0。
  completionPercent      Int       @default(0)
  // 这一天的记录创建时间。
  createdAt              DateTime  @default(now())
  // 勾选练习或完成当天时自动刷新。
  updatedAt              DateTime  @updatedAt

  // 连回计划。计划被删时，14 天的记录一起删。
  program Program @relation(fields: [programId], references: [id], onDelete: Cascade)

  // 同一份计划里，dayIndex 只能出现一次。
  @@unique([programId, dayIndex])
  // 按计划取出它的每一天。
  @@index([programId])
  // 按阶段查找。
  @@index([stage])
  // Postgres 里的真实表名是 program_days。
  @@map("program_days")
}

// 一次 AI 对话。当前 release 暂停新对话，这张表仍保留。
model ChatConversation {
  // 对话主键。
  id        String                 @id @default(cuid())
  // 对话属于哪个用户。
  userId    String
  // 对话围绕哪一份计划。
  programId String
  // 对话状态，新建时是 ACTIVE。
  status    ChatConversationStatus @default(ACTIVE)
  // 对话创建时间。
  createdAt DateTime               @default(now())
  // 对话更新时自动刷新。
  updatedAt DateTime               @updatedAt

  // 连回用户。用户被删时，对话一起删。
  user User @relation(fields: [userId], references: [id], onDelete: Cascade)
  // 同时对上计划 id 和同一个 userId。
  program Program @relation(fields: [programId, userId], references: [id, userId], onDelete: Cascade)
  // 对话里的消息。
  messages ChatMessage[]

  // 按用户查找对话。
  @@index([userId])
  // 按计划查找对话。
  @@index([programId])
  // Postgres 里的真实表名是 chat_conversations。
  @@map("chat_conversations")
}

// 对话中的一条消息。
model ChatMessage {
  // 消息主键。
  id             String          @id @default(cuid())
  // 属于哪一次对话。
  conversationId String
  // 发言角色：用户、助手或系统。
  role           ChatMessageRole
  // 消息正文。
  content        String
  // 回复引用的资料。没有引用时为空。
  citationsJson  Json?
  // 产生这条回复的提供方，例如 gemini 或 groq。用户消息可以不写。
  provider       String?
  // 使用的模型名。用户消息可以不写。
  model          String?
  // 是否触发了安全升级。缺省为 false。
  escalated      Boolean         @default(false)
  // 这次调用的 token 用量。没有用量时为空。
  tokenUsageJson Json?
  // 消息写入时间。这张表没有 updatedAt，消息按创建后不再修改来设计。
  createdAt      DateTime        @default(now())

  // 连回对话。对话被删时，消息一起删。
  conversation ChatConversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)

  // 按对话取出它的消息。
  @@index([conversationId])
  // 按写入时间排序或筛选。
  @@index([createdAt])
  // 查找被标记为安全升级的消息。
  @@index([escalated])
  // Postgres 里的真实表名是 chat_messages。
  @@map("chat_messages")
}

// 知识库中的一篇来源文档。当前 release 的聊天暂停，表仍保留。
model KnowledgeDocument {
  // 文档主键。
  id           String              @id @default(cuid())
  // 来源类别，取上面的 KnowledgeSourceType。
  sourceType   KnowledgeSourceType
  // 文档标题。
  title        String
  // 文档短名，和来源、版本一起唯一。
  slug         String
  // 文档版本。
  version      String
  // 额外元数据。可以不写。
  metadataJson Json?
  // 文档创建时间。
  createdAt    DateTime            @default(now())
  // 文档更新时自动刷新。
  updatedAt    DateTime            @updatedAt

  // 这篇文档切出来的片段。
  chunks KnowledgeChunk[]

  // 同一来源、同一 slug、同一版本只能有一篇。
  @@unique([sourceType, slug, version])
  // 按来源类别查找。
  @@index([sourceType])
  // Postgres 里的真实表名是 knowledge_documents。
  @@map("knowledge_documents")
}

// 知识库文档中的一个片段。向量检索要用原始 SQL，不能用普通 Prisma 字段读写 embedding。
model KnowledgeChunk {
  // 片段主键。
  id           String  @id @default(cuid())
  // 属于哪一篇文档。
  documentId   String
  // 片段在文档里的序号。同一文档里不能重复。
  chunkIndex   Int
  // 片段正文。
  content      String
  // Postgres 的 pgvector 列，1536 维，可空。库上需要先有 vector 扩展。
  // Prisma 生成的客户端没有这个字段的普通读写 API。
  embedding    Unsupported("vector(1536)")?
  // 用来辅助检索的关键词。
  keywords     String[]
  // 片段的额外元数据。可以不写。
  metadataJson Json?
  // 片段创建时间。
  createdAt    DateTime @default(now())
  // 片段更新时自动刷新。
  updatedAt    DateTime @updatedAt

  // 连回文档。文档被删时，片段一起删。
  document KnowledgeDocument @relation(fields: [documentId], references: [id], onDelete: Cascade)

  // 同一文档里，chunkIndex 只能出现一次。
  @@unique([documentId, chunkIndex])
  // 按文档取出它的片段。
  @@index([documentId])
  // Postgres 里的真实表名是 knowledge_chunks。
  @@map("knowledge_chunks")
}

// 市场统计的按天合计。故意不关联用户、档案、购买或计划，避免把个人健康信息写进统计。
model MarketingMetricAggregate {
  // 合计行主键。
  id         String   @id @default(cuid())
  // 统计日期，只保存日期，不保存时刻。
  bucketDate DateTime @db.Date
  // 事件名。
  eventName  String
  // 来源渠道。
  source     String
  // 活动名。
  campaign   String
  // 额外的汇总维度。
  dimension  String
  // 这一格里的次数，新建时是 0。
  count      Int      @default(0)
  // 这一格第一次出现的时间。
  createdAt  DateTime @default(now())
  // 次数增加时自动刷新。
  updatedAt  DateTime @updatedAt

  // 同一天、同一事件、同一来源、同一活动和同一维度只有一行。
  @@unique([bucketDate, eventName, source, campaign, dimension])
  // 按日期和事件名查找合计。
  @@index([bucketDate, eventName])
  // 按来源、活动和日期查找合计。
  @@index([source, campaign, bucketDate])
  // Postgres 里的真实表名是 marketing_metric_aggregates。
  @@map("marketing_metric_aggregates")
}

// NextAuth 的外部账号表。字段名使用适配器要求的下划线写法，不能改成驼峰。
model Account {
  // 账号记录主键。
  id                String  @id @default(cuid())
  // 这个外部账号属于哪个用户。
  userId            String
  // NextAuth 账号类型，例如 email。
  type              String
  // 登录提供方，例如 email。
  provider          String
  // 提供方那边的账号 id。和 provider 一起唯一。
  providerAccountId String
  // OAuth 刷新令牌。魔法链接登录通常不写。
  refresh_token     String?
  // OAuth 访问令牌。魔法链接登录通常不写。
  access_token      String?
  // 访问令牌到期时间，单位是秒。没有令牌时为空。
  expires_at        Int?
  // 令牌类型。没有令牌时为空。
  token_type        String?
  // 提供方授权范围。没有时为空。
  scope             String?
  // OpenID Connect 的 id token。没有时为空。
  id_token          String?
  // 提供方返回的 session state。没有时为空。
  session_state     String?

  // 连回用户。用户被删时，外部账号记录一起删。
  user User @relation(fields: [userId], references: [id], onDelete: Cascade)

  // 同一个提供方下，同一个外部账号只能绑定一次。
  @@unique([provider, providerAccountId])
  // 按用户查找他的外部账号。
  @@index([userId])
  // Postgres 里的真实表名是 accounts。
  @@map("accounts")
}

// NextAuth 的登录会话。浏览器里的 session token 对上这里的一行。
model Session {
  // 会话主键。
  id           String   @id @default(cuid())
  // 发给浏览器的会话令牌。全表唯一。
  sessionToken String   @unique
  // 会话属于哪个用户。
  userId       String
  // 会话到期时间。过期后不能再当作已登录。
  expires      DateTime

  // 连回用户。用户被删时，会话一起删。
  user User @relation(fields: [userId], references: [id], onDelete: Cascade)

  // 按用户查找会话。
  @@index([userId])
  // Postgres 里的真实表名是 sessions。
  @@map("sessions")
}

// 魔法链接的一次性验证令牌。它不直接关联 User，identifier 通常是邮箱。
model VerificationToken {
  // 这份令牌要验证的对象，魔法链接里通常是邮箱。
  identifier String
  // 一次性令牌。全表唯一。用过或过期后，应用层不再接受它。
  token      String   @unique
  // 令牌到期时间。当前登录链接的有效期是 15 分钟。
  expires    DateTime

  // 同一个 identifier 加同一个 token 只能有一行。
  @@unique([identifier, token])
  // Postgres 里的真实表名是 verification_tokens。
  @@map("verification_tokens")
}

